package cli

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func probeLongTag(n int) string { return "v1.0.0-" + strings.Repeat("a", n) }

func probePack(t *testing.T, root, tag string) {
	// write a packed ref directly (filenames > 255 bytes are not possible as loose refs)
	head := strings.TrimSpace(releaseGitOut(t, root, "rev-parse", "HEAD"))
	f, err := os.OpenFile(filepath.Join(root, ".git", "packed-refs"), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	if _, err := f.WriteString(head + " refs/tags/" + tag + "\n"); err != nil {
		t.Fatal(err)
	}
}

func TestB38R10ClaudeProbe_LongTagBeforeGovernedTag(t *testing.T) {
	for _, n := range []int{20, 65000, 65536, 70000} {
		root := t.TempDir()
		writeReleaseFixture(t, root, ".pose/policy/release.json", `{"schema_version":1,"adopted_at":"2026-08-03","provider":"github","repository":"owner/repo","allow_empty":true,"legacy_cutoff":"v0.1.0","version_source":{"path":"VERSION","kind":"text"}}`)
		writeReleaseFixture(t, root, "VERSION", "1.0.0\n")
		releaseGit(t, root, "init", "-q")
		releaseGit(t, root, "add", ".")
		releaseGit(t, root, "commit", "-q", "-m", "no manifest")
		probePack(t, root, "v0.0.1-"+strings.Repeat("a", n)) // legacy, sorts before v1.0.0
		releaseGit(t, root, "tag", "v1.0.0")                   // governed, no manifest anywhere
		listed := releaseGitOut(t, root, "tag", "--list", "v*")
		checker, out := releaseCheckerFor(root)
		t.Logf("n=%d listed_lines=%d errors=%d out=%.200q", n, strings.Count(listed, "\n"), checker.errors, out.String())
	}
}

func TestB38R10ClaudeProbe_NonReleaseTagWithoutPolicy(t *testing.T) {
	for _, tag := range []string{"v1.0", "vendor-drop", "v1.0.0"} {
		root := t.TempDir()
		writeReleaseFixture(t, root, "README", "x\n")
		releaseGit(t, root, "init", "-q")
		releaseGit(t, root, "add", ".")
		releaseGit(t, root, "commit", "-q", "-m", "plain project")
		releaseGit(t, root, "tag", tag)
		checker, out := releaseCheckerFor(root)
		t.Logf("tag=%s errors=%d out=%q", tag, checker.errors, out.String())
	}
}

func releaseGitOut(t *testing.T, root string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", append([]string{"-C", root}, args...)...)
	cmd.Env = append(os.Environ(), "GIT_AUTHOR_NAME=t", "GIT_AUTHOR_EMAIL=t@e", "GIT_COMMITTER_NAME=t", "GIT_COMMITTER_EMAIL=t@e")
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git %v: %v", args, err)
	}
	return string(out)
}

func TestB38R10ClaudeProbe_LostGitDir(t *testing.T) {
	for _, dropPolicy := range []bool{false, true} {
		root := adoptedTaggedRelease(t)
		if c, out := releaseCheckerFor(root); c.errors != 0 {
			t.Fatalf("control %q", out.String())
		}
		_ = os.RemoveAll(filepath.Join(root, ".pose", "releases"))
		if dropPolicy {
			_ = os.Remove(filepath.Join(root, ".pose", "policy", "release.json"))
		}
		c1, out1 := releaseCheckerFor(root)
		_ = os.Rename(filepath.Join(root, ".git"), filepath.Join(root, "moved-git"))
		_ = os.WriteFile(filepath.Join(root, ".git"), []byte("gitdir: "+filepath.Join(root, "lost-gitdir")+"\n"), 0o644)
		c2, out2 := releaseCheckerFor(root)
		t.Logf("dropPolicy=%v withGit errors=%d %.150q | lostGitDir errors=%d %.150q", dropPolicy, c1.errors, out1.String(), c2.errors, out2.String())
	}
}
